insert into schemes (slug, name, name_mr, name_hi, level, state, summary, benefits, eligibility, required_documents, application_url, official_source, last_verified)
values
('pm-kisan','Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)','पंतप्रधान किसान सन्मान निधी','प्रधानमंत्री किसान सम्मान निधि','central',null,
 'Income support of Rs 6,000 per year paid in three instalments to eligible landholding farmer families.',
 'Rs 6,000 per year in three instalments of Rs 2,000, transferred directly to the bank account.',
 array['Landholding farmer family with cultivable land in the applicant''s name','Aadhaar-linked bank account','Excludes institutional landholders, income-tax payers, government employees and specified pensioners'],
 array['Aadhaar card','Land records / 7-12 extract','Bank passbook','Mobile number'],
 'https://pmkisan.gov.in/','Ministry of Agriculture and Farmers Welfare, Government of India',current_date),
('pmfby','Pradhan Mantri Fasal Bima Yojana (PMFBY)','पंतप्रधान पीक विमा योजना','प्रधानमंत्री फसल बीमा योजना','central',null,
 'Crop insurance against notified natural risks for enrolled farmers, with premium shared by government.',
 'Claim-based crop insurance. Farmer premium is 2% of sum insured for kharif food and oilseed crops, 1.5% for rabi, and 5% for commercial/horticultural crops.',
 array['Notified crop and area in the current season','Enrolment before the cut-off date through bank, CSC or portal','Aadhaar and bank account linked to the applicant'],
 array['Aadhaar card','Bank passbook','Land records','Sowing certificate / self-declaration as required','Crop and area details'],
 'https://pmfby.gov.in/','Ministry of Agriculture and Farmers Welfare, Government of India',current_date),
('kcc','Kisan Credit Card (KCC)','किसान क्रेडिट कार्ड','किसान क्रेडिट कार्ड','central',null,
 'Short-term credit for crop production and allied activities with interest subvention on prompt repayment.',
 'Credit limit based on crop plan and landholding. Interest subvention of 2% plus 3% prompt repayment incentive is available within scheme limits and applicable guidelines.',
 array['Farmer with cultivable land or eligible tenant/ oral lessee as per bank policy','KYC-compliant applicant','Satisfactory repayment record for renewal'],
 array['Identity proof','Address proof','Land records / tenancy proof','Passport-size photograph','Bank account details'],
 'https://www.myscheme.gov.in/schemes/kcc','Department of Financial Services / participating banks',current_date),
('pm-kusum','PM-KUSUM (Solar pumps and solar power)','पीएम-कुसुम (सौर पंप व सौर ऊर्जा)','पीएम-कुसुम (सौर पंप और सौर ऊर्जा)','central',null,
 'Promotes solar irrigation pumps and decentralised solar power for farmers, with capital subsidy and grid connection components.',
 'Component B supports standalone solar pumps; Component C supports grid-connected solar plants on barren/fallow land. Subsidy and capacity depend on the state and component.',
 array['Farmer with agricultural land and a valid electricity/irrigation connection where required','Application through the state nodal agency (MEDA in Maharashtra)','Eligibility and capacity limits vary by component and state'],
 array['Aadhaar card','Land records','Bank passbook','Electricity connection details where applicable','Photograph'],
 'https://pmkusum.mnre.gov.in/','Ministry of New and Renewable Energy, Government of India',current_date),
('soil-health-card','Soil Health Card Scheme','मृदा आरोग्य पत्रिका योजना','मृदा स्वास्थ्य कार्ड योजना','central',null,
 'Provides soil test based nutrient recommendations to farmers through state soil testing laboratories.',
 'Soil samples are tested for pH, organic carbon, available nitrogen, phosphorus, potassium and micronutrients where available; a card with crop-wise fertiliser advice is issued.',
 array['Farmer with agricultural land in a covered district','Sample collection through state agriculture department / KVK as notified'],
 array['Aadhaar or farmer registration details','Land survey number / 7-12 extract','Mobile number'],
 'https://soilhealth.dac.gov.in/','Department of Agriculture and Farmers Welfare, Government of India',current_date),
('enam','National Agriculture Market (eNAM)','राष्ट्रीय कृषी बाजार (ई-नाम)','राष्ट्रीय कृषि बाजार (ई-नाम)','central',null,
 'Online trading platform connecting farmers to participating APMC mandis for transparent price discovery.',
 'Farmers can sell eligible commodities through participating mandis, view bids and receive payment through the mandi settlement process.',
 array['Farmer registered with a participating APMC mandi','Aadhaar and bank account','Commodity must be tradable on eNAM at that mandi'],
 array['Aadhaar card','Bank passbook','Mobile number','Mandi/APMC registration details'],
 'https://enam.gov.in/','Small Farmers'' Agribusiness Consortium (SFAC), Government of India',current_date),
('aif','Agriculture Infrastructure Fund (AIF)','कृषी पायाभूत सुविधा निधी','कृषि अवसंरचना कोष','central',null,
 'Medium-long term financing for post-harvest management and community farming assets with interest subvention.',
 'Loan up to the scheme limit for eligible projects, with 3% interest subvention and credit guarantee support as per current guidelines.',
 array['Farmer, FPO, PACS, agri-entrepreneur or eligible entity','Bankable project for post-harvest/community infrastructure','Project viability and land/lease documents as required by the lender'],
 array['Project report','KYC documents','Land records or lease agreement','Bank account details','Statutory approvals where applicable'],
 'https://agriinfra.dac.gov.in/','Department of Agriculture and Farmers Welfare, Government of India',current_date),
('mahadbt','MahaDBT — Maharashtra state scheme portal','महाडीबीटी — महाराष्ट्र राज्य योजना portal','महाडीबीटी — महाराष्ट्र राज्य योजना पोर्टल','state','Maharashtra',
 'Single-window portal for many Maharashtra farmer welfare, subsidy and scholarship schemes.',
 'Scheme-specific benefits. Always check the current scheme listing, eligibility and cut-off dates on MahaDBT before applying.',
